// %g with precision 6, matching glibc printf / default std::cout for float.
pub fn fmt_g6(x: f32) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".to_string() } else { "nan".to_string() };
    }
    if x.is_infinite() {
        return if x.is_sign_negative() { "-inf".to_string() } else { "inf".to_string() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".to_string() } else { "0".to_string() };
    }
    const P: i32 = 6;
    // Correctly-rounded (round-half-to-even) scientific form with P significant digits.
    let sci = format!("{:.*e}", (P - 1) as usize, x); // e.g. "-1.45846e-6"
    let epos = sci.rfind('e').unwrap();
    let mant = &sci[..epos];
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= P {
        let m = strip_zeros(mant);
        let sign = if exp < 0 { '-' } else { '+' };
        let a = exp.abs();
        if a < 100 { format!("{}e{}{:02}", m, sign, a) } else { format!("{}e{}{}", m, sign, a) }
    } else {
        let decimals = (P - 1 - exp) as usize;
        let s = format!("{:.*}", decimals, x);
        strip_zeros(&s)
    }
}
fn strip_zeros(s: &str) -> String {
    if s.contains('.') {
        let t = s.trim_end_matches('0');
        let t = t.strip_suffix('.').unwrap_or(t);
        t.to_string()
    } else { s.to_string() }
}
