include!("gfmt.rs");
fn gray(r: f32, g: f32, b: f32) -> f32 { 0.2126f32*r + 0.7152f32*g + 0.0722f32*b }
fn ok(v: f32) -> bool { v == 0.0 || (v.is_finite() && v.abs() >= f32::MIN_POSITIVE) || v.is_infinite() }
fn arg(v: f32) -> String {
    if v.is_infinite() { return if v.is_sign_negative() {"-inf".into()} else {"inf".into()} }
    format!("{:e}", v)
}
fn ulp_step(v: f32, d: i32) -> f32 {
    let b = v.to_bits() as i64;
    f32::from_bits(((b + d as i64) as u64 & 0xffffffff) as u32)
}
/// find (r,g,b) whose grayscale is exactly T
fn solve(t: f32) -> Option<(f32,f32,f32)> {
    for (ci, c) in [(0usize, 0.2126f32), (1, 0.7152f32), (2, 0.0722f32)] {
        let x0 = (t as f64 / c as f64) as f32;
        for d in -4..=4i32 {
            let x = ulp_step(x0, d);
            if !ok(x) || x == 0.0 { continue; }
            let got = match ci { 0 => gray(x,0.0,0.0), 1 => gray(0.0,x,0.0), _ => gray(0.0,0.0,x) };
            if got.to_bits() == t.to_bits() {
                return Some(match ci {0=>(x,0.0,0.0), 1=>(0.0,x,0.0), _=>(0.0,0.0,x)});
            }
        }
    }
    None
}
struct R(u64);
impl R { fn n(&mut self)->u64{let mut x=self.0;x^=x<<13;x^=x>>7;x^=x<<17;self.0=x;x} }
fn main(){
    let mode = std::env::args().nth(1).unwrap_or_default();
    let mut tests: Vec<(f32,f32,f32)> = Vec::new();
    let mut targets: Vec<f32> = Vec::new();
    // 1. boundaries: halfway points d.ddddd5 * 10^e for e in -45..=38
    for e in -44i32..=38 {
        for m in [1.0f64, 9.999995, 9.99999, 1.000001, 1.0000005, 9.9999949, 9.9999951,
                  1.5, 2.5, 1.234565, 1.234575, 5.0, 9.5, 1.05, 1.000000] {
            for d in -2..=2i32 {
                let v = (m * 10f64.powi(e)) as f32;
                if v.is_finite() { targets.push(ulp_step(v, d)); }
            }
        }
    }
    // 2. all N.5 six-digit ties and neighbours
    for n in [100000i32,123456,199999,499999,500000,555555,999996,999998,999999,864197] {
        for h in [0.0f32, 0.5, 0.25, 0.75] { targets.push(n as f32 + h); targets.push(-(n as f32 + h)); }
    }
    // 3. every power of ten neighbourhood
    for e in -45i32..=38 { let v=(10f64.powi(e)) as f32; if v.is_finite() { for d in -3..=3 { targets.push(ulp_step(v,d)); } } }
    let mut rng = R(0xdeadbeefcafe1234);
    // 4. random f32 across whole range (both signs), incl subnormals
    for _ in 0..40000 { let b = rng.n() as u32; let v = f32::from_bits(b); if v.is_finite() { targets.push(v); } }
    // 5. dense small-integer-scaled
    for _ in 0..8000 { let m=(rng.n()%10_000_000) as f64; let e=(rng.n()%80) as i32 -45;
        let v=(m*10f64.powi(e)) as f32; if v.is_finite(){targets.push(v); targets.push(-v);} }
    let mut unsolved = 0usize;
    for t in &targets {
        match solve(*t) { Some(x) => tests.push(x), None => { unsolved += 1; } }
    }
    // 6. cancellation cases -> subnormals / exact zero, no target control needed
    for _ in 0..6000 {
        let e = (rng.n()%8) as i32;
        let a = f32::from_bits((f32::MIN_POSITIVE.to_bits() as u64 + (rng.n()% (1<<22))) as u32) * (1<<e) as f32;
        if !ok(a) { continue; }
        let b = (-(0.2126f64*a as f64)/0.0722f64) as f32;
        if !ok(b) { continue; }
        tests.push((a, 0.0, b));
        let g = (-(0.2126f64*a as f64)/0.7152f64) as f32;
        if ok(g) { tests.push((a, g, 0.0)); }
    }
    // 7. inf / large
    for v in [f32::MAX, f32::MIN, f32::INFINITY, f32::NEG_INFINITY, 3.4028235e38, -3.4028235e38] {
        tests.push((v,0.0,0.0)); tests.push((0.0,v,0.0)); tests.push((0.0,0.0,v));
    }
    if mode=="args" {
        let mut s=String::new();
        for (r,g,b) in &tests { s.push_str(&format!("{}\t{}\t{}\n", arg(*r),arg(*g),arg(*b))); }
        print!("{}",s);
    } else if mode=="exp" {
        let mut s=String::new();
        for (r,g,b) in &tests {
            let y=gray(*r,*g,*b);
            s.push_str(&format!("{} {} {} {} {} {}\n", fmt_g6(1.0f32-*r),fmt_g6(1.0f32-*g),fmt_g6(1.0f32-*b),fmt_g6(y),fmt_g6(y),fmt_g6(y)));
        }
        print!("{}",s);
    } else {
        eprintln!("tests={} unsolved_targets={}", tests.len(), unsolved);
        // distribution report
        let mut sub=0; let mut sci=0; let mut fixd=0;
        for (r,g,b) in &tests { let y=gray(*r,*g,*b);
            if y!=0.0 && y.abs()<f32::MIN_POSITIVE {sub+=1;}
            let s=fmt_g6(y); if s.contains('e'){sci+=1;} else {fixd+=1;} }
        eprintln!("grayscale outputs: subnormal={} scientific={} fixed={}", sub, sci, fixd);
    }
}
